  const adapter = new KernelAdapter();
  adapter.registerTools([toolDescriptorFromPi({ name: "read", description: "read" })]);
  await adapter.beginTask("probe", "probe");

  // 1. What does a REPLANNING task emit at the refusal site?
  (adapter as any).task = { ...adapter.currentTask!, status: "REPLANNING" };
  const d = await adapter.precheckToolCall("read", "execute", { path: "x" }, undefined, "c1");
  console.log("REPLANNING reason:", d.decision.reason);

  // 2. Can a FAILED task ever become REPLANNING? (terminal -> live)
  const adapter2 = new KernelAdapter();
  adapter2.registerTools([toolDescriptorFromPi({ name: "read", description: "read" })]);
  await adapter2.beginTask("probe2", "probe2");
  (adapter2 as any).task = { ...adapter2.currentTask!, status: "REPLANNING", failureReason: "INJECTED" };
  const d2 = await adapter2.precheckToolCall("read", "execute", { path: "x" }, undefined, "c1");
  console.log("REPLANNING+injected reason:", d2.decision.reason);

  // 3. Where does failureReason come from at all? Walk the recorded transitions.
  const a3 = new KernelAdapter();
  a3.registerTools([toolDescriptorFromPi({ name: "read", description: "read" })]);
  await a3.beginTask("p3", "p3");
  await a3.precheckToolCall("read", "execute", { path: "README.md" }, undefined, "c1");
  const bound = await a3.beginToolExecution("c1", "read", { path: "README.md" });
  await a3.recordToolResult("c1", "read", { content: "nope" }, false);
  await a3.finishTask({ answer: "x" });
  for (const t of a3.transitionLog) {
    console.log("LOG", t.from, "->", t.to, "fr=", JSON.stringify(t.failureReason));
  }
});

